    idealAnswerHi: "\u092f\u0939 \u092c\u0947\u092f\u0938 \u0925\u094d\u092f\u094b\u0930\u092e \u092a\u0930 \u0906\u0927\u093e\u0930\u093f\u0924 \u0939\u0948 \u0914\u0930 \u092f\u0939 '\u0928\u093e\u0926\u093e\u0928' (Naive) \u092e\u093e\u0928 \u0932\u0947\u0924\u093e \u0939\u0948 \u0915\u093f \u0938\u092d\u0940 \u092b\u0940\u091a\u0930\u094d\u0938 \u090f\u0915-\u0926\u0942\u0938\u0930\u0947 \u0938\u0947 \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0939\u0948\u0902\u0964 \u092f\u0939 \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u0914\u0930 \u0938\u094d\u092a\u0948\u092e \u0921\u093f\u091f\u0947\u0915\u094d\u0936\u0928 \u092e\u0947\u0902 \u092c\u0939\u0941\u0924 \u0924\u0947\u091c \u0914\u0930 \u0905\u0938\u0930\u0926\u093e\u0930 \u0939\u0948\u0964",
